import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
// Using the exact Lucide set from your Citizen files
import { Truck, Map, Package, User, Bell, Settings, ChevronRight, Zap, Activity, ShieldCheck, Box } from 'lucide-react';

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState('route');
  const scrollRef = useRef(null);

  const tabs = [
    { id: 'route', icon: <Map size={24} />, label: 'NAV', color: '#FF5B03' },
    { id: 'logs', icon: <Truck size={24} />, label: 'LOGS', color: '#CAD23C' },
    { id: 'inventory', icon: <Box size={24} />, label: 'LOAD', color: '#A1AED1' },
    { id: 'id', icon: <User size={24} />, label: 'ID', color: '#FFB6A9' },
  ];

  return (
    <div className="h-screen w-full bg-[#FFF24D] font-sans overflow-hidden perspective-1000">

      {/* --- WORKER HUD (Matching your Citizen Header style) --- */}
      <header className="fixed top-0 w-full pt-12 px-10 flex justify-between items-end z-50">
        <div>
          <h4 className="text-[#47510B] font-black text-[10px] uppercase tracking-[0.5em] opacity-60">Operator_Node / 09</h4>
          <h2 className="text-5xl font-[1000] italic text-[#47510B] uppercase tracking-tighter leading-none">
            Worker<span className="text-[#FF5B03]">.</span>
          </h2>
        </div>
        <div className="flex gap-4">
          <button className="bg-white/40 backdrop-blur-md p-4 rounded-[24px] border border-white/50 text-[#47510B] shadow-xl">
            <Settings size={22} />
          </button>
          <div className="bg-[#47510B] p-1.5 pr-6 rounded-[24px] flex items-center gap-4 border-2 border-white shadow-2xl text-[#CAD23C]">
            <div className="w-10 h-10 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]">
                <ShieldCheck size={20} />
            </div>
            <span className="font-black text-[12px] uppercase tracking-widest text-white">Unit_404</span>
          </div>
        </div>
      </header>

      {/* --- MAIN CONTENT: Horizontal Snap (Matching your Citizen Dashboard) --- */}
      <main className="h-full w-full flex overflow-x-auto snap-x snap-mandatory no-scrollbar">

        {/* SECTION 1: NAVIGATION / ROUTE */}
        <section className="min-w-full h-full snap-start flex items-center justify-center px-10 pt-20">
          <div className="relative w-full max-w-[1100px] h-[550px] scale-[0.95]">

            {/* Primary Route Card - Using your Heavy Shadow style */}
            <div className="absolute top-0 left-0 w-[65%] h-[420px] bg-white rounded-[70px] 
                            shadow-[0_30px_0_0_#47510B] p-12 z-10 hover:-translate-y-2 transition-all duration-500">
               <div className="flex justify-between items-start mb-8">
                  <div className="w-16 h-16 bg-[#FF5B03] rounded-[24px] flex items-center justify-center text-white shadow-2xl">
                    <Map size={32} strokeWidth={3} />
                  </div>
                  <div className="bg-[#CAD23C] px-4 py-2 rounded-full font-black text-[10px] text-[#47510B] uppercase tracking-widest">Active_Path</div>
               </div>
               <h2 className="text-8xl font-black italic uppercase tracking-tighter leading-[0.8] text-[#47510B]">
                  Sector <br/> <span className="text-[#FF5B03]">09_East.</span>
               </h2>
               <div className="mt-12 flex items-center gap-4 text-[#A1AED1]">
                  <Activity size={20} />
                  <span className="font-black text-xs uppercase tracking-[0.3em]">Traffic_Optimized</span>
               </div>
            </div>

            {/* Shift Progress - Using your "Tuck" Card style */}
            <div className="absolute top-10 right-0 w-[40%] h-[350px] bg-[#AB1717] rounded-[70px] 
                            shadow-[0_30px_0_0_#47510B] p-10 z-20 flex flex-col justify-between border-4 border-white/20">
                <Zap size={40} className="text-[#CAD23C]" />
                <div>
                   <p className="text-7xl font-black text-white leading-none tracking-tighter italic">85<span className="text-2xl opacity-50">%</span></p>
                   <p className="text-[10px] font-black uppercase text-white/40 tracking-widest mt-2">Shift_Complete</p>
                </div>
            </div>
          </div>
        </section>

        {/* Other sections would go here similarly... */}
      </main>

      {/* --- TACTICAL DOCK (Matching your Citizen Footer) --- */}
      <footer className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50">
        <nav className="bg-[#A1AED1]/90 backdrop-blur-2xl border border-white/30 px-5 py-4 rounded-[45px] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] flex items-center gap-4">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-4 px-8 py-5 rounded-[32px] transition-all duration-500 group ${
                activeTab === tab.id 
                ? "bg-white shadow-2xl scale-110" 
                : "text-white/50 hover:text-white"
              }`}
            >
              <div 
                className="group-hover:scale-110 transition-transform"
                style={{ color: activeTab === tab.id ? tab.color : 'inherit' }}
              >
                {tab.icon}
              </div>
              {activeTab === tab.id && (
                <span className="text-[12px] font-black uppercase tracking-tighter italic text-[#47510B]">
                  {tab.label}
                </span>
              )}
            </button>
          ))}
        </nav>
      </footer>
    </div>
  );
};

export default WorkerDashboard;
